    $('pageContent').innerHTML=header('Histórico de alterações','Registro permanente de quem fez cada alteração e dos valores envolvidos.')+`<section class="panel table-scroll"><table><thead><tr><th>DATA</th><th>RESPONSÁVEL</th><th>OPERAÇÃO</th><th>REGISTRO</th><th></th></tr></thead><tbody>${data.items.map(a=>`<tr><td>${esc(new Date(a.created_at.replace(' ','T')+'Z').toLocaleString('pt-BR'))}</td><td>${esc(a.actor_email)}</td><td>${esc(auditActions[a.action]||a.action)}</td><td>${esc(entities[a.entity]||a.entity)} #${esc(a.entity_id)}</td><td><button data-action="audit-details" data-audit-id="${a.id}">Ver valores</button></td></tr>`).join('')}</tbody></table><div class="pagination"><span>${data.total} registros · página ${page}</span><button data-action="audit-prev"${page<=1?' disabled':''}>Anterior</button><button data-action="audit-next"${page*50>=data.total?' disabled':''}>Próxima</button></div></section>`;
